const item = $input.first()?.json;
const message = item?.message || item?.edited_message;

if (!message || !message.text) return [];

const messageDate = message.date;
const now = Math.floor(Date.now() / 1000);

// Use 24 hours (86400s) window so testing with older messages still works
if (Math.abs(now - messageDate) > 86400) return [];

return [{ json: item }];

const message = $input.first().json.message.text;
const match = message.match(/mangadex\.org\/chapter\/([a-f0-9-]+)/i);

if (!match) throw new Error('Could not extract chapter ID');

// --- BGM LIBRARY (all tracks) ---
const allBgmTracks = [
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype1_imagination.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype2_sakura_mitsutsuki.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype3_gurenge.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype4_kick_back.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype5_kaikai_kitan.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/love1_ai_no_scenario.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/love2_pride_kakumei.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad1_dakara_boku.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad2_ref_rain.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad3_yukitoki.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad4_kataomoi.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/chill1_hitchcock.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/chill2_vidro_moyou.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/chill3_sparkle.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic1_barricades.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic2_homura.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic3_boy.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic4_tot_musica.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/Banda%20Kaam%20Ka%20pagalall.com.mp3"
];

// Random BGM selection
const bgmUrl = allBgmTracks[Math.floor(Math.random() * allBgmTracks.length)];
const bgmName = bgmUrl.split('/').pop().replace('.mp3','').replace(/%20/g,' ');
const outroUrl = "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/outro.jpg";

return [{
  json: {
    chapterId: match[1],
    chatId: String($input.first().json.message.chat.id),
    bgmUrl: bgmUrl,
    bgmName: bgmName,
    outroUrl: outroUrl
  }
}];

const mdData = $('Get MD Cover').first().json;
const gelData = $input.first().json;
const extractData = $('Extract Chapter ID').first().json;

// Construct MD Cover URL
let mdCoverUrl = '';
try {
  const mangaId = mdData.data.id;
  const coverFile = mdData.data.relationships.find(r => r.type === 'cover_art').attributes.fileName;
  mdCoverUrl = `https://uploads.mangadex.org/covers/${mangaId}/${coverFile}`;
} catch (e) { console.log('MD Cover Error', e); }

// Get Gelbooru URL
let gelUrl = '';
try {
  if (gelData.post && gelData.post.length > 0) {
    gelUrl = gelData.post[0].file_url;
  } else if (Array.isArray(gelData) && gelData.length > 0 && gelData[0].file_url) {
      gelUrl = gelData[0].file_url;
  }
} catch (e) { console.log('Gelbooru Error', e); }

// Decide
const finalCover = gelUrl || mdCoverUrl || extractData.outroUrl;

return [{
  json: {
    ...extractData,
    mangadexCover: mdCoverUrl,
    gelbooruCover: gelUrl,
    coverUrl: finalCover
  }
}];

