const raw = $input.first().json.data || '';
const m = raw.match(/data:\s*\[([^\]]+)\]/g);
if (m && m.length) {
  const p = JSON.parse(m[m.length-1].replace('data: ',''));
  const v = p[1];
  const s = p[0] || '';
  const tm = s.match(/Done!\s*(.+?)\s*-\s*Ch\./i);
  const cm = s.match(/Ch\.?(\d+)/i);

  const mangaTitle = tm ? tm[1].trim() : 'Manga';
  const chapterNum = cm ? cm[1] : '';

  // Extract video URL - handle both string and object formats
  let videoUrl = '';
  if (typeof v === 'string') {
    videoUrl = v;
  } else if (v && v.url) {
    videoUrl = v.url;
  } else if (v && v.video && v.video.url) {
    videoUrl = v.video.url;
  }

  // Generate SEO-optimized hashtag from manga title
  const mangaHashtag = mangaTitle.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();

  // Enhanced Instagram Caption with SEO
  const instagramCaption = `${mangaTitle} - Chapter ${chapterNum} ✨

🔥 New chapter just dropped! Watch the manga come to life!

📖 Manga: ${mangaTitle}
📑 Chapter: ${chapterNum}

💬 Follow for daily manga reels!

#manga #anime #mangareels #${mangaHashtag} #otaku #webtoon #mangatok #animeedit #manhwa #mangatiktok #animereels #japanmanga #mangaart #mangapanel #animefan #webtoonrecommendation #mangalover #animelovers`;

  // Enhanced YouTube Title & Description with #Shorts
  const youtubeTitle = `${mangaTitle} - Chapter ${chapterNum} | Manga Reel #Shorts #Manga #Anime`;

  const youtubeDescription = `${mangaTitle} - Chapter ${chapterNum} - Watch the manga come to life!

🔥 New manga chapter animated as a vertical reel!

📖 Manga: ${mangaTitle}
📑 Chapter: ${chapterNum}

👍 Like & Subscribe for more manga content!
🔔 Turn on notifications to never miss a upload!

━━━━━━━━━━━━━━━━━━━━━━━━━━
📌 Tags:
#Shorts #manga #anime #${mangaHashtag} #mangareels #otaku #webtoon #mangatok #animeedit #manhwa #mangatiktok #animereels #japanmanga #mangaart #animefan #webtoonrecommendation #animeshorts #mangashorts
━━━━━━━━━━━━━━━━━━━━━━━━━━

⚠️ All content belongs to the original manga creators. This video is for entertainment and promotional purposes only.`;

  return [{
    json: {
      status: s,
      mangaTitle: mangaTitle,
      chapterNum: chapterNum,
      video_url: videoUrl,
      chatId: $('Extract Chapter ID').first().json.chatId,
      bgmName: $('Extract Chapter ID').first().json.bgmName,
      outroUrl: $('Extract Chapter ID').first().json.outroUrl,
      instagramCaption: instagramCaption,
      youtubeTitle: youtubeTitle,
      youtubeDescription: youtubeDescription
    }
  }];
}
